/* Généré par tools/ck_build.py depuis data/ck/ : ne pas modifier à la main. */
window.CK_HYP={"avc-hemorragique":{"bloquant":true,"confirmation":"Le diagnostic est posé par l’imagerie cérébrale, qui montre l’hématome dans le tissu cérébral.","exam":{"lignes":[{"mecanisme":"Une artère rompue saigne dans le cerveau, et l’hématome peut grossir dans les premières heures.","nom":"Scanner cérébral sans injection en urgence","pourquoi_ce_choix":"Il est rapide et distingue l’hémorragie de l’ischémie, ce qui décide de tout le traitement : une thrombolyse est exclue.","precautions":"L’équipe recherche d’emblée un traitement anticoagulant, car sa neutralisation est urgente.","principe":"Le scanner sans injection montre l’hématome, son siège, son volume et une extension dans les ventricules.","rang":1,"recherche":"Il montre l’hématome, son siège, son volume et une extension dans les ventricules.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1, Additional information","lu_le":"2026-10-17"},{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une angiographie normale au scanner n’exclut pas une malformation ; l’artériographie numérisée reste l’examen de référence.","mecanisme":"Chez le sujet jeune, un hématome lobaire ou cérébelleux sans hypertension connue peut venir d’une anomalie des vaisseaux.","nom":"Angioscanner, IRM ou angio-IRM","pourquoi_ce_choix":"Ces examens se font sans cathétérisme et en urgence, ce qui les place avant l’artériographie.","principe":"L’imagerie vasculaire montre une malformation artérioveineuse, un anévrisme, une fistule durale, une malformation caverneuse ou une thrombose veineuse.","rang":2,"recherche":"Elle recherche une cause macrovasculaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1 et 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une petite malformation vasculaire peut échapper à l’angioscanner.","nom":"Artériographie numérisée par cathétérisme","pourquoi_ce_choix":"C’est l’examen de référence des malformations ; on le garde pour une suspicion qui persiste malgré un angioscanner normal.","precautions":"Elle est invasive, avec environ 0,6 % de complications ; l’indication se décide au cas par cas.","principe":"Un cathéter injecte le produit de contraste directement dans les artères, ce qui donne une image plus fine.","rang":3,"recherche":"Elle recherche une malformation vasculaire que l’angioscanner n’a pas montrée.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-hemorragique","label":"Hémorragie intracérébrale spontanée","pec":{"mesures_generales":["Le patient est admis dans une unité de l’AVC organisée, sauf s’il relève des soins intensifs.","Un avis neurochirurgical est demandé tôt en cas d’hématome volumineux, d’hémorragie dans les ventricules ou d’hématome compressif de la fosse postérieure.","Un dépistage des troubles de la déglutition est fait, et aucune décision de non-réanimation n’est prise dans les 24 premières heures sauf volonté claire du patient."],"moyens_specifiques":[{"limites":"La baisse ne dépasse pas 70 mmHg et la pression ne descend pas sous 110 mmHg ; la recommandation ne porte pas sur les hématomes plus volumineux.","mecanisme":"Une pression artérielle élevée s’associe à l’expansion de l’hématome, au décès et à la dépendance.","pourquoi_ce_choix":"Cette mesure ne demande ni geste invasif ni centre spécialisé, et la ligne directrice la propose pour les hématomes de petit ou moyen volume.","principe":"Abaisser tôt la pression vise à prévenir l’expansion de l’hématome et l’aggravation clinique.","src":[{"id":"R-ESO-ICH","loc":"Blood pressure management ; PICO 2, Expert consensus statements","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La pression systolique est abaissée sous 140 mmHg dans les 6 heures pour un hématome de moins de 30 millilitres. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le niveau de preuve reste faible ou très faible pour les antidotes, et le risque d’événements thromboemboliques doit être pesé.","mecanisme":"Sous anticoagulant, la coagulation est diminuée, et l’hématome risque davantage de grossir.","pourquoi_ce_choix":"Le moyen dépend de la molécule : concentré de complexe prothrombinique avec vitamine K intraveineuse sous antivitamine K, idarucizumab sous dabigatran, andexanet alfa ou concentré de complexe prothrombinique sous inhibiteur du facteur Xa.","principe":"On rétablit la coagulation en neutralisant l’anticoagulant le plus vite possible.","src":[{"id":"R-ESO-ICH","loc":"PICO 3.3.1 à 3.3.2.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’anticoagulant est neutralisé en urgence par un moyen adapté à la molécule. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le bénéfice n’est pas uniforme, et la décision reste individuelle après un avis neurochirurgical.","mecanisme":"L’hématome comprime le cerveau, et ses produits de dégradation déclenchent une inflammation qui ajoute une lésion secondaire.","pourquoi_ce_choix":"Elle n’est proposée que si le siège, le volume, l’état neurologique, le délai et l’expérience de l’équipe la rendent favorable, car les essais donnent des résultats différents selon ces facteurs.","principe":"On retire l’hématome pour lever la compression et limiter la lésion secondaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 4.1 ; Surgery, Analysis of current evidence","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une évacuation chirurgicale d’un hématome supratentoriel peut être proposée.","type":"chirurgie"}],"objectif":"Le traitement vise à limiter l’expansion de l’hématome et les complications pour réduire le décès et la dépendance."},"src":[{"id":"R-ESO-ICH","loc":"Abstract ; PICO 1 à 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"avc-ischemique":{"bloquant":true,"confirmation":"Le diagnostic repose sur un déficit neurologique focal brutal avec une imagerie qui exclut une hémorragie ; l’IRM de diffusion montre l’infarctus.","exam":{"lignes":[{"alternative":"Lors d’un AVC constaté au réveil, une IRM qui montre un décalage diffusion-FLAIR permet encore la thrombolyse si une thrombectomie n’est pas prévue.","mecanisme":"Un caillot bouche une artère du cerveau ; autour du cœur de l’infarctus, une zone mal perfusée reste récupérable pendant quelques heures.","nom":"Imagerie cérébrale en urgence (scanner sans injection ou IRM)","pourquoi_ce_choix":"Le bénéfice de la reperfusion baisse avec le temps : l’examen le plus rapide qui exclut une hémorragie passe donc en premier. L’IRM convient aussi si elle ne retarde pas le traitement.","precautions":"Sous antivitamine K, la thrombolyse n’est faite que si l’INR est connu et ne dépasse pas 1,7 ; après un anticoagulant oral direct pris dans les 48 heures, elle exige un dosage spécifique.","principe":"Le scanner sans injection montre une hémorragie, qui interdit la thrombolyse, et l’étendue des signes précoces d’ischémie.","rang":1,"recherche":"Elle recherche une hémorragie et l’étendue des signes précoces d’ischémie.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h ; 4,5 à 9 h ; AVC grave (ASPECTS)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Quand le caillot bouche une grosse artère de la circulation antérieure, il menace un vaste territoire et peut être retiré mécaniquement.","nom":"Angioscanner ou angio-IRM des vaisseaux cervicaux et intracrâniens","pourquoi_ce_choix":"Elle seule désigne les patients qui gagnent à une thrombectomie : celle-ci améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si les critères des essais sont remplis.","precautions":"Les précautions du produit de contraste (fonction rénale, allergie) restent À vérifier dans une source suisse ou européenne.","principe":"L’injection opacifie les artères et montre l’endroit où le flux s’arrête.","rang":2,"recherche":"Elle recherche l’occlusion d’une grosse artère de la circulation antérieure.","src":[{"id":"R-ESO-MT","loc":"PICO 1 et 2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le délai seul ne dit pas si le tissu est perdu : chez certains patients, une zone récupérable persiste au-delà de 4,5 heures.","nom":"Imagerie de perfusion (scanner ou IRM)","pourquoi_ce_choix":"Elle ne sert qu’au-delà de 4,5 heures ou si l’heure de début est inconnue, car le scanner sans injection ne montre pas ce tissu récupérable ; dans les 4,5 heures, elle ne doit pas retarder la thrombolyse.","principe":"Elle compare le cœur de l’infarctus et la zone mal perfusée ; leur décalage quantifie le tissu encore récupérable.","rang":3,"recherche":"Elle mesure le cœur de l’infarctus et la zone mal perfusée encore récupérable.","src":[{"id":"R-ESO-IVT","loc":"Recommandations 4,5 à 9 h et AVC du réveil","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"PICO 2, critères DEFUSE-3 et DAWN","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-ischemique","label":"Accident vasculaire cérébral ischémique","pec":{"mesures_generales":["Le patient rejoint sans délai un centre de l’AVC, et l’équipe note l’heure de début ou celle où il a été vu sans déficit pour la dernière fois.","Une pression artérielle supérieure à 185/110 mmHg doit être abaissée avant la thrombolyse ; si elle reste plus haute, la thrombolyse n’est pas faite.","Aucun antithrombotique n’est donné dans les 24 heures qui suivent la thrombolyse."],"moyens_specifiques":[{"limites":"Elle augmente le risque d’hémorragie cérébrale symptomatique, d’environ 3 % avec l’altéplase : une hémorragie doit donc être exclue avant. Elle n’est pas faite si la pression reste au-dessus de 185/110 mmHg, si l’INR dépasse 1,7 sous antivitamine K, ou après un anticoagulant oral direct pris dans les 48 heures sans dosage spécifique.","mecanisme":"Le caillot prive de sang une zone qui meurt en quelques heures si le flux ne revient pas.","pourquoi_ce_choix":"Elle se donne par simple injection, sans attendre un centre de thrombectomie, et améliore le pronostic dans les 4,5 heures. La ténectéplase, plus spécifique de la fibrine et de durée d’action plus longue, se donne en une seule injection ; la ligne directrice la propose avant une thrombectomie.","principe":"On rétablit le flux en dissolvant le caillot : un médicament thrombolytique est injecté dans une veine.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h, > 80 ans, ténectéplase, pression artérielle, anticoagulants ; hémorragie symptomatique","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombolyse intraveineuse par altéplase ou ténectéplase se fait dans les 4,5 heures, y compris après 80 ans. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elle ne concerne que l’occlusion d’une grosse artère prouvée par l’imagerie et exige un centre spécialisé ; ses complications propres restent À vérifier dans une source européenne.","mecanisme":"Un caillot dans une grosse artère menace un vaste territoire cérébral.","pourquoi_ce_choix":"Elle vise une reperfusion complète de la grosse artère ; elle améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si l’imagerie montre encore du tissu récupérable selon les critères des essais. La ligne directrice admet les deux techniques de retrait.","principe":"On rétablit le flux en retirant le caillot par un cathéter, avec un stent retriever ou par aspiration au contact.","src":[{"id":"R-ESO-MT","loc":"PICO 1, 2 et 8 ; Organisation des soins (mothership, drip-and-ship)","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombectomie mécanique se fait dans un centre de l’AVC qui la pratique, en plus de la thrombolyse quand celle-ci est indiquée.","type":"interventionnel"}],"objectif":"Le traitement vise à rétablir le plus vite possible la perfusion du cerveau encore viable pour améliorer le pronostic fonctionnel."},"src":[{"id":"R-ESO-IVT","loc":"Résumé et recommandations","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"Résumé","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 Présentation typique","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"bell":{"bloquant":false,"confirmation":"Le diagnostic est retenu devant une paralysie faciale périphérique installée en 12 à 72 heures, sans autre cause trouvée à l’examen et aux examens ciblés.","exam":{"lignes":[{"mecanisme":"Une paralysie faciale périphérique a une autre cause que la paralysie de Bell dans 25 à 40 % des cas.","nom":"Examen neurologique complet et otoscopie","pourquoi_ce_choix":"Ce sont des gestes immédiats qui écartent les causes graves ou spécifiques avant de retenir un diagnostic d’exclusion.","precautions":"Une atteinte bilatérale, plusieurs nerfs crâniens atteints, un spasme facial ou une évolution chronique sont atypiques et font rechercher une autre cause.","principe":"L’examen neurologique cherche d’autres déficits, et l’otoscopie cherche une cause dans l’oreille.","rang":1,"recherche":"Ils recherchent un autre déficit neurologique et des vésicules du conduit auditif externe, une otite moyenne ou un cholestéatome.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; Die wichtigsten Empfehlungen ; § 2.2","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire ; chez l’adulte, la ligne directrice allemande la recommande, alors que le protocole des HUG la réserve aux présentations atypiques.","mecanisme":"Une neuroborréliose, un diabète ou une infection peuvent donner le même tableau.","nom":"Sérologie de Borrelia, glycémie et hémoglobine glyquée ; sérologies VIH et syphilis selon le protocole des HUG","pourquoi_ce_choix":"La ligne directrice exige au moins la sérologie de Borrelia, car la neuroborréliose se traite par antibiotique et non par corticoïde ; une sérologie du virus varicelle-zona s’ajoute en cas de suspicion de zona.","principe":"Le sang montre des anticorps contre Borrelia, une glycémie élevée ou les marqueurs d’une infection.","rang":2,"recherche":"Elles recherchent une neuroborréliose, un diabète et une cause infectieuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 4 Examens complémentaires","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une tumeur ou une lésion du rocher peut imiter une paralysie de Bell, et la perte axonale détermine la récupération.","nom":"IRM et électroneuromyographie (ENMG)","pourquoi_ce_choix":"L’IRM n’est indiquée qu’en cas de présentation atypique ; l’ENMG vers le 10e jour évalue le pronostic des formes sévères.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète.","principe":"L’IRM montre un processus le long du trajet du nerf ; l’ENMG mesure la réponse des muscles à la stimulation du nerf.","rang":3,"recherche":"L’IRM recherche un processus de l’angle ponto-cérébelleux, du rocher, de la parotide ou du tronc cérébral ; l’ENMG mesure la perte axonale.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 ; § 2.4 Bildgebung","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"bell","label":"Paralysie faciale idiopathique (paralysie de Bell)","pec":{"mesures_generales":["La sévérité est cotée selon House-Brackmann, et le patient est revu ; une forme sévère (grades IV à VI) est revue en neurologie vers le 10e jour.","Une grossesse ne change pas la conduite, mais la corticothérapie débute de préférence à l’hôpital avec un avis obstétrical."],"moyens_specifiques":[{"limites":"Le bénéfice n’est démontré que si le traitement débute dans les 72 heures ; des troubles du sommeil ont été rapportés, et les contre-indications restent À vérifier dans l’information professionnelle suisse.","mecanisme":"La cause reste discutée : la ligne directrice cite une inflammation auto-immune, une réactivation du virus herpès simplex de type 1 et des facteurs ischémiques.","pourquoi_ce_choix":"C’est le seul traitement dont les essais montrent qu’il favorise la récupération complète et réduit les syncinésies, avec un nombre de sujets à traiter de 10 ; un antiviral seul n’apporte pas ce bénéfice.","principe":"Le corticoïde agit contre la composante inflammatoire de l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 1 Einführung ; Die wichtigsten Empfehlungen ; Tabelle 3 et 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale débute dans les 72 heures. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Il ne remplace jamais le corticoïde ; la décision se prend au cas par cas après information du patient.","mecanisme":"Une réactivation du virus herpès simplex de type 1 fait partie des causes discutées.","pourquoi_ce_choix":"Il ne s’ajoute que dans les formes sévères, où il peut apporter un bénéfice supplémentaire : grades V et VI selon la ligne directrice allemande, grades IV à VI ou suspicion de zona selon le protocole des HUG.","principe":"Un antiviral freine la multiplication du virus en plus de l’effet du corticoïde.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un antiviral peut s’ajouter au corticoïde dans les formes sévères. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"},{"limites":"Le délai et le choix de la technique restent À vérifier dans une source suisse ou européenne.","mecanisme":"Quand le nerf ne récupère pas, la paralysie devient définitive.","pourquoi_ce_choix":"Ces gestes ne se discutent qu’après l’échec de la récupération spontanée, qui reste la règle dans la paralysie de Bell.","principe":"On aide la fermeture des paupières ou l’on apporte au visage une autre commande nerveuse ou un autre muscle.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.2 Nicht medikamentöse Therapie","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une charge palpébrale ou une réanimation microchirurgicale peut être proposée (anastomose du nerf hypoglosse sur le nerf facial, greffe transfaciale, transfert musculaire).","type":"chirurgie"}],"objectif":"Le traitement vise une récupération complète et la prévention des séquelles, synergie et lésion de la cornée."},"src":[{"id":"R-DGN-BELL","loc":"Die wichtigsten Empfehlungen ; § 1 ; § 2 ; § 3","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule","vii-site3-tympanique","vii-site4-mastoidien"]},"cholesteatome":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie, l’examen ORL et l’imagerie.","exam":{"lignes":[{"mecanisme":"Le cholestéatome grossit dans l’oreille moyenne et érode l’os jusqu’au canal facial ; la paralysie s’installe lentement.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple et immédiate, et un début lent de la paralysie doit la faire répéter avec soin.","principe":"L’otoscopie montre le cholestéatome dans l’oreille moyenne.","rang":1,"recherche":"Elle recherche le cholestéatome dans l’oreille moyenne.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’extension du cholestéatome et l’atteinte du canal facial décident de la chirurgie.","nom":"Examen ORL et imagerie du rocher","pourquoi_ce_choix":"La ligne directrice demande un examen ORL et une IRM devant un processus du rocher ; le choix précis de l’imagerie reste À vérifier.","principe":"L’examen ORL et l’imagerie précisent l’extension et l’état du canal facial.","rang":2,"recherche":"Ils précisent l’extension du cholestéatome et l’atteinte du canal facial.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.4 ; § 2.5","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"cholesteatome","label":"Cholestéatome","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source suisse ou européenne.","mecanisme":"Le cholestéatome comprime et érode le canal facial.","pourquoi_ce_choix":"Le choix et les modalités de l’intervention restent À vérifier dans une source suisse ou européenne.","principe":"On retire le cholestéatome pour libérer le nerf.","statut":"À vérifier","texte":"Le cholestéatome est retiré par une chirurgie de l’oreille moyenne.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à enlever le cholestéatome et à libérer le nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"fracture-rocher":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’imagerie du rocher.","exam":{"lignes":[{"mecanisme":"Un traumatisme crânien peut fracturer le rocher et léser le nerf dans son canal osseux.","nom":"Scanner haute résolution du rocher","pourquoi_ce_choix":"Le choix du scanner plutôt que de l’IRM pour l’os n’est pas encore sourcé par une ligne directrice lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"Le scanner haute résolution montre l’os en détail, donc le trait de fracture et le canal facial.","rang":1,"recherche":"Il recherche le trait de fracture et son rapport avec le canal facial.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf ; c’est le seul examen qui chiffre l’atteinte.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"fracture-rocher","label":"Fracture du rocher","pec":{"mesures_generales":["Un avis ORL est demandé.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source européenne.","mecanisme":"Un fragment osseux peut comprimer le nerf, ou le nerf peut être sectionné.","pourquoi_ce_choix":"Les critères qui la font préférer à l’abstention restent À vérifier dans une source européenne.","principe":"On décomprime ou l’on répare le nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Une intervention chirurgicale sur le canal facial peut être indiquée.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à préserver ou à rétablir la continuité du nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site2-genicule","vii-site4-mastoidien"]},"neuroborreliose":{"bloquant":false,"confirmation":"La neuroborréliose est certaine si le liquide cérébrospinal inflammatoire montre une synthèse intrathécale d’anticorps spécifiques ou une PCR ou une culture positive.","exam":{"lignes":[{"mecanisme":"La bactérie Borrelia, transmise par une tique, peut atteindre les racines nerveuses et les nerfs crâniens.","nom":"Sérologie de Borrelia (test immuno-enzymatique puis immunoblot)","pourquoi_ce_choix":"C’est un examen sanguin simple que la ligne directrice sur la paralysie faciale exige ; il se demande en cas de suspicion clinique suffisante.","precautions":"La sérologie peut rester négative au tout début de la maladie.","principe":"L’organisme produit des anticorps contre Borrelia : le test immuno-enzymatique les dépiste, et l’immunoblot les confirme.","rang":1,"recherche":"Elle recherche des anticorps IgM et IgG contre Borrelia dans le sang.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"Objectifs ; § 3.3 ; § 3.10","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire devant une paralysie faciale périphérique.","mecanisme":"L’infection du système nerveux déclenche une réaction inflammatoire dans le liquide cérébrospinal.","nom":"Ponction lombaire avec index d’anticorps spécifiques","pourquoi_ce_choix":"Elle seule rend le diagnostic probable ou certain, ce qui fait choisir l’antibiotique et renoncer aux corticoïdes.","principe":"La ponction montre l’inflammation, et l’index d’anticorps prouve que les anticorps se forment dans le système nerveux lui-même.","rang":2,"recherche":"Elle recherche une inflammation du liquide cérébrospinal, une rupture de la barrière hémato-encéphalique et une synthèse intrathécale d’anticorps contre Borrelia.","src":[{"id":"R-DGN-NB","loc":"§ 3.2 ; § 3.4 ; § 3.10, critères diagnostiques ; § 5.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"neuroborreliose","label":"Neuroborréliose (maladie de Lyme)","pec":{"mesures_generales":["L’efficacité du traitement se juge sur l’évolution clinique.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les contre-indications de chaque antibiotique restent À vérifier dans l’information professionnelle suisse.","mecanisme":"Une infection bactérienne entretient l’atteinte du nerf.","pourquoi_ce_choix":"La doxycycline orale est aussi efficace que les bêtalactamines intraveineuses, avec la même tolérance ; le choix tient compte des allergies, de la grossesse et du mode d’administration. La limite d’âge de 8 ans pour la doxycycline chez l’enfant est levée.","principe":"Un antibiotique élimine la bactérie.","src":[{"id":"R-DGN-NB","loc":"Statements 4 et 5 ; recommandations 14 et 24 ; durée","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une antibiothérapie par doxycycline, ceftriaxone, céfotaxime ou pénicilline G dure 14 jours dans la forme précoce. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Cette règle ne vaut que si le diagnostic est probable ou certain selon les critères du liquide cérébrospinal.","mecanisme":"La paralysie vient ici d’une infection, et non d’une inflammation idiopathique.","pourquoi_ce_choix":"La ligne directrice ne recommande pas d’ajouter des corticoïdes quand la neuroborréliose est probable ou certaine.","principe":"On traite la cause par l’antibiotique, sans ajouter de traitement contre l’inflammation.","src":[{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Aucun corticoïde n’est ajouté à l’antibiotique.","type":"pharmaco"}],"objectif":"Le traitement vise à éradiquer Borrelia et à obtenir la récupération du nerf, qui est presque toujours bonne."},"src":[{"id":"R-DGN-NB","loc":"§ 3.10 ; § 5","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 ; § 2.6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site4-mastoidien"]},"otite-moyenne-compliquee":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie et l’examen ORL.","exam":{"lignes":[{"mecanisme":"Une infection de l’oreille moyenne peut atteindre le nerf facial qui longe la paroi de la caisse du tympan.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple, immédiate et fait partie de tout examen d’une paralysie faciale périphérique.","principe":"L’otoscopie montre l’inflammation du tympan, un écoulement ou un cholestéatome.","rang":1,"recherche":"Elle recherche une otite moyenne aiguë ou chronique et un cholestéatome.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection peut s’étendre à la mastoïde et toucher l’audition.","nom":"Examen ORL spécialisé","pourquoi_ce_choix":"La ligne directrice le demande devant toute anomalie de l’oreille, de la mastoïde, du tympan ou de l’audition.","principe":"Le spécialiste examine l’oreille moyenne, la mastoïde et le tympan, et il teste l’audition.","rang":2,"recherche":"Il évalue l’oreille moyenne, la mastoïde, le tympan et l’audition.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5, dernier alinéa","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une infection grave peut détruire l’os et découvrir le nerf.","nom":"Imagerie du rocher","pourquoi_ce_choix":"L’IRM est indiquée devant un processus du rocher ; le choix entre scanner et IRM reste À vérifier.","principe":"L’imagerie montre une mastoïdite ou une destruction osseuse.","rang":3,"recherche":"Elle recherche une mastoïdite ou une destruction osseuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"otite-moyenne-compliquee","label":"Otite moyenne compliquée de paralysie faciale","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les contre-indications restent À vérifier dans une source suisse ou européenne.","mecanisme":"L’infection et l’inflammation de l’oreille moyenne compriment le nerf.","pourquoi_ce_choix":"Le choix entre ces moyens reste À vérifier dans une source suisse ou européenne.","principe":"On contrôle l’infection et l’on draine l’oreille moyenne.","statut":"À vérifier","texte":"L’ORL choisit entre antibiothérapie, paracentèse et chirurgie de la mastoïde.","type":"autre"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à contrôler l’infection de l’oreille moyenne et à décomprimer le nerf."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.5","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"schwannome-vestibulaire":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’IRM ; une confirmation histologique n’est pas toujours nécessaire.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur bénigne de la gaine du nerf vestibulaire grossit lentement dans le méat acoustique interne et l’angle ponto-cérébelleux.","nom":"IRM du méat acoustique interne et de l’angle ponto-cérébelleux, T1 avec gadolinium","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; la même technique sert à la surveillance.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Le gadolinium rehausse la tumeur sur les séquences T1, ce qui montre sa taille et son extension.","recherche":"Elle montre la tumeur, sa taille et son extension dans le méat acoustique interne.","src":[{"id":"R-EANO-VS","loc":"Diagnostic Procedures, Imaging ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"schwannome-vestibulaire","label":"Schwannome vestibulaire","pec":{"mesures_generales":["Le dossier est discuté en réunion de concertation pluridisciplinaire, et une chirurgie se fait dans un centre à grand volume.","L’œil est protégé en cas de lagophtalmie."],"moyens_specifiques":[{"limites":"Elle suppose un suivi régulier ; une croissance ou de nouveaux symptômes imposent un traitement.","mecanisme":"Une petite tumeur bénigne peut rester stable longtemps.","pourquoi_ce_choix":"Elle évite les risques d’un traitement chez un patient peu symptomatique.","principe":"On surveille la croissance et l’audition, et l’on ne traite que si la tumeur progresse.","src":[{"id":"R-EANO-VS","loc":"Therapeutic Strategies, Observation ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La tumeur est surveillée par IRM et audiométrie, chaque année pendant 5 ans.","type":"suivi"},{"limites":"Elle menace le nerf facial et l’audition ; le monitorage du nerf facial améliore le résultat, et l’opération se fait dans un centre à grand volume.","mecanisme":"Une grosse tumeur comprime le tronc cérébral et les nerfs voisins.","pourquoi_ce_choix":"C’est l’option de la grosse tumeur compressive, car la radiochirurgie ne convient qu’aux petits volumes.","principe":"On retire la tumeur, en totalité ou en partie, pour lever la compression.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Surgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une exérèse chirurgicale est faite avec monitorage du nerf facial, suivie au besoin d’une radiothérapie ou d’une radiochirurgie.","type":"chirurgie"},{"limites":"Elle ne convient pas aux grosses tumeurs compressives, et la tumeur reste en place sous surveillance.","mecanisme":"Une petite tumeur ou un reste après chirurgie peut continuer de grossir.","pourquoi_ce_choix":"Elle évite une ouverture du crâne pour une petite tumeur ou une récidive après chirurgie.","principe":"Une irradiation très ciblée vise à arrêter la croissance de la tumeur sans l’enlever.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Radiosurgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une radiochirurgie est proposée.","type":"interventionnel"}],"objectif":"Le traitement vise à contrôler la tumeur en préservant la fonction faciale et l’audition."},"src":[{"id":"R-EANO-VS","loc":"Abstract ; Diagnostic Procedures ; Therapeutic Strategies","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]},"traumatisme-facial":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’examen des rameaux.","exam":{"lignes":[{"mecanisme":"Une plaie de la joue peut sectionner un ou plusieurs rameaux du nerf après sa sortie du crâne.","nom":"Examen de la plaie et cotation rameau par rameau","pourquoi_ce_choix":"La conduite à tenir n’est pas encore sourcée par une ligne directrice suisse ou européenne lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"On teste chaque territoire du visage pour savoir quel rameau ne répond plus.","rang":1,"recherche":"Il recherche le ou les rameaux atteints et une plaie de la parotide.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf, ce que l’examen clinique seul ne montre pas.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"traumatisme-facial","label":"Plaie ou traumatisme des rameaux du nerf facial","pec":{"mesures_generales":["Un avis ORL ou de chirurgie maxillo-faciale est demandé."],"moyens_specifiques":[{"limites":"Les limites et la récupération attendue restent À vérifier dans une source suisse ou européenne.","mecanisme":"Un rameau sectionné ne transmet plus la commande au muscle.","pourquoi_ce_choix":"Le choix entre suture et greffe, et le délai, restent À vérifier dans une source suisse ou européenne.","principe":"On rétablit la continuité du nerf.","statut":"À vérifier","texte":"Le nerf est suturé ou réparé par une greffe nerveuse.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à rétablir la continuité du nerf et à protéger l’œil."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site5-extracranien"]},"tumeur-cerebrale":{"bloquant":false,"confirmation":"Le diagnostic définitif repose sur l’examen histologique et moléculaire du tissu tumoral.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur qui grandit dans le cerveau donne un déficit progressif selon son siège.","nom":"IRM cérébrale sans et avec gadolinium (T2, FLAIR, T1 3D avant et après injection)","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; il prépare aussi le prélèvement et la chirurgie.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Plusieurs séquences distinguent la tumeur du tissu sain, et le gadolinium montre les zones qui prennent le contraste.","recherche":"Elle détecte la tumeur, la situe et précise sa prise de contraste.","src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"tumeur-cerebrale","label":"Tumeur cérébrale","pec":{"mesures_generales":["Une décision de soins sans diagnostic tissulaire reste exceptionnelle."],"moyens_specifiques":[{"limites":"L’étendue de l’exérèse se limite quand la tumeur touche une zone fonctionnelle ; la suite du traitement dépend du type tumoral et reste hors de ce pilote.","mecanisme":"Le type exact de la tumeur, défini par l’histologie et la biologie moléculaire, décide du traitement.","pourquoi_ce_choix":"Une même intervention donne le diagnostic et traite ; une biopsie seule se réserve aux tumeurs qu’on ne peut pas enlever sans risque.","principe":"On prélève ou l’on enlève la tumeur pour obtenir le tissu et réduire la masse.","src":[{"id":"R-EANO-GLIO","loc":"Tissue acquisition ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une chirurgie première, à visée diagnostique et thérapeutique, est le plus souvent réalisée.","type":"chirurgie"}],"objectif":"Le traitement vise à obtenir un diagnostic tissulaire puis à traiter la tumeur selon son type."},"src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Tissue acquisition","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"tumeur-parotide":{"bloquant":false,"confirmation":"Le diagnostic est confirmé par la cytologie ou l’histologie ; une paralysie faciale avant l’opération est un facteur de mauvais pronostic.","exam":{"lignes":[{"mecanisme":"Une tumeur maligne de la parotide peut envahir le nerf facial, qui traverse la glande.","nom":"Palpation et échographie des parties molles de la face et du cou","pourquoi_ce_choix":"Elle est rapide, disponible chez l’ORL, et elle guide ensuite la cytoponction.","principe":"L’échographie montre la masse dans la glande et les ganglions du cou.","rang":1,"recherche":"Elles recherchent une masse parotidienne et des adénopathies.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung, dernier alinéa","lu_le":"2026-10-17"},{"id":"R-ESMO-SGC","loc":"Diagnostic work-up","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une biopsie au trocart s’impose si la cytoponction ne permet pas de conclure.","mecanisme":"Seule l’étude des cellules distingue une tumeur maligne d’une tumeur bénigne.","nom":"Cytoponction à l’aiguille fine guidée par échographie","pourquoi_ce_choix":"C’est le prélèvement le moins invasif, et une confirmation cytologique ou histologique est obligatoire avant la chirurgie.","principe":"L’aiguille fine aspire des cellules, et le système de Milan classe le risque de malignité.","rang":2,"recherche":"Elle recherche des cellules malignes et classe le risque selon le système de Milan.","src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Un scanner avec injection la remplace si l’IRM est contre-indiquée.","mecanisme":"La tumeur peut s’étendre le long des nerfs et vers les ganglions.","nom":"IRM de la parotide et du cou","pourquoi_ce_choix":"C’est l’imagerie préférée quand une tumeur maligne est suspectée.","principe":"L’IRM montre les tissus mous en détail, dont l’extension le long des nerfs.","rang":3,"recherche":"Elle précise l’extension locale, le long des nerfs et vers les ganglions.","src":[{"id":"R-ESMO-SGC","loc":"Recommendations, imagerie","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"tumeur-parotide","label":"Tumeur maligne de la parotide","pec":{"mesures_generales":["Le patient est informé, avant l’opération, qu’une chirurgie plus étendue peut être nécessaire.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"La résection du nerf laisse une paralysie que seule une reconstruction peut améliorer ; les traitements complémentaires restent À vérifier dans la ligne directrice.","mecanisme":"La tumeur envahit le nerf ; une paralysie avant l’opération signale cette invasion et un moins bon pronostic.","pourquoi_ce_choix":"Une exérèse complète est le traitement de référence, et un nerf déjà paralysé ne garde pas de fonction à préserver.","principe":"On retire toute la glande avec la tumeur, et le nerf envahi avec elle.","src":[{"id":"R-ESMO-SGC","loc":"Surgical management of the primary ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une parotidectomie totale est faite ; un nerf facial paralysé avant l’opération est réséqué puis reconstruit.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise une exérèse complète de la tumeur avec une prise en charge du nerf facial."},"src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Surgical management","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 3 Diagnostic différentiel","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site5-extracranien"]},"zona-oticus":{"bloquant":false,"confirmation":"Le diagnostic est clinique devant une paralysie faciale périphérique avec otalgie et vésicules auriculaires ; la sérologie le confirme.","exam":{"lignes":[{"mecanisme":"Le virus varicelle-zona réactivé atteint le nerf et la peau de son territoire sensitif, la conque et le conduit auditif.","nom":"Otoscopie et examen de la conque","pourquoi_ce_choix":"C’est un examen immédiat et sans risque qui change le traitement, car le zona impose un antiviral rapide.","precautions":"Une douleur très intense sans vésicule doit faire évoquer un zona sans éruption.","principe":"L’otoscopie montre les vésicules, même quand elles se limitent au conduit ou au tympan.","rang":1,"recherche":"Elle recherche des vésicules du conduit auditif externe, du tympan ou de la conque.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-CEN-NC9","loc":"Nerf facial (VII), territoire sensitif","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection virale peut atteindre les méninges.","nom":"Sérologie du virus varicelle-zona et ponction lombaire","pourquoi_ce_choix":"La ligne directrice les demande en cas de suspicion clinique ; ils confirment le diagnostic sans retarder l’antiviral.","principe":"La sérologie montre les anticorps contre le virus, et la ponction lombaire une inflammation du liquide cérébrospinal.","rang":2,"recherche":"Elles confirment l’infection par le virus varicelle-zona et recherchent une atteinte méningée.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen ; Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"zona-oticus","label":"Zona otique (syndrome de Ramsay-Hunt)","pec":{"mesures_generales":["L’antiviral débute sans attendre le résultat des examens.","L’œil est protégé et l’audition est surveillée."],"moyens_specifiques":[{"dose_ref":"valaciclovir-po-adulte-zona","limites":"La dose s’adapte à la fonction rénale ; le bénéfice chiffré sur la récupération faciale n’apparaît pas dans les sources lues.","mecanisme":"Le virus varicelle-zona réactivé se multiplie et abîme le nerf ; le pronostic est moins bon que dans la paralysie de Bell.","pourquoi_ce_choix":"La ligne directrice allemande impose un antiviral rapide dans le zona otique, et le protocole des HUG retient le valaciclovir, qui se prend par la bouche.","principe":"Un antiviral freine la multiplication du virus pour limiter l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.1, alinéa sur le zona otique","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné par voie orale, rapidement et systématiquement ; la posologie suit la ligne suisse liée.","type":"pharmaco"},{"dose_ref":"valaciclovir-po-adulte-zona-ir","limites":"Les paliers de clairance suivent l’information professionnelle suisse liée ; une dialyse impose un avis spécialisé, À vérifier.","mecanisme":"Une insuffisance rénale ralentit l’élimination du valaciclovir.","pourquoi_ce_choix":"Le même antiviral reste utilisable, ce qui évite de changer de molécule chez le patient insuffisant rénal.","principe":"On réduit la dose selon la clairance de la créatinine pour éviter l’accumulation.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné à dose adaptée à la clairance de la créatinine, selon la ligne suisse liée.","type":"pharmaco"},{"limites":"La durée et les contre-indications du corticoïde restent À vérifier dans l’information professionnelle suisse.","mecanisme":"L’inflammation du nerf s’ajoute à l’infection virale.","pourquoi_ce_choix":"Le protocole des HUG associe les deux traitements, car chacun agit sur un mécanisme différent.","principe":"Le corticoïde freine l’inflammation pendant que l’antiviral agit sur le virus.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale est associée à l’antiviral. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à limiter l’atteinte du nerf, dont la récupération est moins souvent complète que dans la paralysie de Bell."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.2, 2.5, 2.6, 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3, 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]}};
